        let mut next = self.clone();
        let track = next.numbered_track();
        let id = track.id;
        next.tracks.insert(0, track);
        (next, id)
    }

    /// How long a plate is: the caller's `duration`, or the whole timeline's
    /// length when it is absent (spec §6).
    ///
    /// The default is snapped even though every clip end already sits on the
    /// grid — a hand-written project file is the case that is not — and it
    /// floors at one frame, because a background of an EMPTY timeline would
    /// otherwise be a zero-length clip, which `validate` refuses and which
    /// is not a thing the timeline can hold.
    ///
    /// A duration the caller GAVE is refused rather than floored, which is
    /// `add_text_clip`'s and `add_shape_clip`'s rule for the same argument
    /// and the envelope's rule for a length (`edit.rs`): a negative or
    /// sub-frame length is a caller's arithmetic mistake, and clamping it
    /// would answer a bug with a clip.
    fn plate_duration(&self, duration: Option<Ticks>) -> Result<Ticks, String> {
        let Some(given) = duration else {
            return Ok(self.snapped(self.duration()).max(self.frame()));
        };
        let snapped = self.snapped(given);
        if snapped < self.frame() {
            return Err(format!(
                "background duration must be at least one frame ({} ticks), not {given}",
                self.frame()
            ));
        }
        Ok(snapped)
    }

    /// Puts a backdrop on a new back-most track, running from 0 for
    /// `duration` — the timeline's own length when that is absent (spec §6).
    ///
    /// With `media`, the clip is shaped as `add_clip` would shape one of
    /// that file in every respect but its scale: the right source kind,
    /// audio props when the file has sound, and a FILL scale where
    /// `add_clip` takes a Fit one — the module doc argues that one
    /// difference. With `color`, or
    /// with neither, it is a canvas-sized filled rectangle with no stroke,
    /// at scale 1 — the rectangle IS the canvas, so there is nothing for
    /// Fit to do and writing the 1 outright keeps it exact whatever
    /// `fit_new_clips` says. Either way the clip is named "Background".
    ///
    /// A plate the user then re-colours in the inspector's Fill row is the
    /// whole of the "Solid Color" command, and it is also how a full-canvas
    /// GRADIENT becomes reachable: a gradient is a shape's fill, so the
    /// gradient background the road map asks for is this clip with a
    /// `set_shape` after it.
    ///
    /// `Err` for `media` and `color` together (they are alternatives, and a
    /// caller that named both meant one of them), for an unknown media, for
    /// a media with no pictures to show, for a colour outside 0–1, and for a
    /// duration under a frame — and, through [`Project::finish`], when the
    /// extra track or clip would break a reader cap. Never an identity: the clip
    /// lands on a track of its own, so there is nothing here to refuse
    /// quietly.
    ///
    /// A timed media — video or audio — IS clamped to its own length,
    /// whether the duration was given or defaulted to the timeline's (spec
    /// §11, D4-4). It reads [`Project::whole_media_length`], which is what
    /// `add_clip` gives a clip of the same file, so the plate ends where
    /// its file does and its segment plays at rate 1. What that paragraph
    /// used to say — that an unclamped plate "shows nothing" past the end
    /// of its media — was measured FALSE: the plan stretched a six-second
    /// file over a twelve-second plate at rate 0.5. An image plate is
    /// unclamped still, having no source bound at all.
    pub fn add_background(
        &self,
        media: Option<u32>,
        color: Option<Color>,
        duration: Option<Ticks>,
    ) -> Result<Outcome, String> {
        if let (Some(media), Some(_)) = (media, color) {
            return Err(format!(
                "add_background takes a media or a color, not both (media {media})"
            ));
        }
        let mut duration = self.plate_duration(duration)?;

        // Everything that can refuse is decided against `self`, before a
        // track exists to leave behind.
        let (source, video, audio, shape) = match media {
            Some(id) => {
                let found = self.require_media(id)?.clone();
                let has_pixels = found.has_video || matches!(found.kind, MediaKind::Image);
                if !(has_pixels && found.width > 0 && found.height > 0) {
                    return Err(format!(
                        "media {id} has no pixel size, so it cannot be a background"
                    ));
                }
                let source = match found.kind {
                    MediaKind::Image => Source::Image { media: id },
                    MediaKind::Video | MediaKind::Audio => {
                        // A timed plate is held INSIDE its own file, by the
                        // same function `add_clip` measures a whole media
                        // with — so the plate's two `Err` sentences are
                        // that op's, and the segment plays at rate 1
                        // (spec §11, D4-4).
                        duration = duration.min(self.whole_media_length(&found)?);
                        Source::Media {
                            media: id,
                            r#in: 0,
                            reversed: false,
                        }
                    }
                    // Unreached: a LUT's row has no pixels, refused above.
                    MediaKind::Lut => return Err(crate::lut::lut_not_placeable(id)),
                };
                // FILL, not `add_clip`'s Fit: a plate that leaves the canvas
                // showing down one side has failed at the one thing a
                // background is for, and whether Fit leaves it showing
                // depends on `canvas.fit_new_clips`, which has no opinion
                // about backgrounds. The module doc argues it at length.
                let video = VideoProps {
                    scale: self.fill_scale(f64::from(found.width), f64::from(found.height)),
                    ..VideoProps::default()
                };
                (
                    source,
                    video,
                    found.has_audio.then(AudioProps::default),
                    None,
                )
            }
            None => {
                let plate = ShapeProps {
                    kind: ShapeKind::Rectangle,
                    width: f64::from(self.canvas.width),
                    height: f64::from(self.canvas.height),
                    stroke: None,
                    fill: Some(color.unwrap_or(DEFAULT_PLATE)),
                    ..ShapeProps::default()
                };
                // The caller's colour reaches the same check a `set_shape`
                // of it would, so `[0, 0, 255, 1]` is named here rather
                // than blown out on the canvas.
                check_shape(&plate)?;
                (Source::Shape, VideoProps::default(), None, Some(plate))
            }
        };

        let (mut next, track) = self.with_back_track();
        let clip = Clip {
            video: Some(video),
            audio,
            shape,
            name: Some(BACKGROUND_NAME.to_string()),
            ..Clip::placed(next.allocate_id(), track, 0, duration, source)
        };
        next.clips.push(clip);
        self.finish(next)
    }

    /// Copies `clip` onto a new back-most track, blown up to fill the canvas
    /// and blurred — the screencast backdrop (spec §6).
    ///
    /// The copy keeps the source, the in point, the start, the duration and
    /// the speed, so it plays the SAME FRAMES as the clip in front of it and
    /// stays exact under any later trim of its own; it drops its audio, its
    /// duck, its transition, its actions and its identity, and it takes a
    /// fill scale, a centred position, no crop, a `normal` blend and one
    /// full-strength blur. The module doc argues each of those.
    ///
    /// **A NEST clip is refused**, and it is the one refusal here that is
    /// not about a missing size — a nest has a frozen canvas and
    /// `Project::source_size` answers with it. It is about the BLUR.
    /// Flattening
    /// (`nest.rs`) folds a nest clip's PLACEMENT down onto the layers inside
    /// it and drops every per-pixel property it carries: a nest clip never
    /// becomes a layer of its own, so `recipe.rs::layer` reads `filters`,
    /// the colour controls, the chroma key, the shadow, the reflection, the
    /// spotlight, the hidden regions and the blend off the INNER clip and
    /// never off the nest clip. The blur this op writes would therefore
    /// reach nothing, and the command would report success having minted a
    /// SHARP 1.5× duplicate of the nest sitting behind the original, at
    /// double the render cost — a wrong picture answered with no message,
    /// which is the failure shape this crate refuses by name everywhere
    /// else. It is the same call `edit_props.rs`'s `check_blend` makes about
    /// `video.blend` on a nest clip, and `clamp_video`'s about an end patch
    /// carrying one; a blur is a per-pixel property like any other. The way
    /// in is the round trip the rest of the crate already uses for a nest —
    /// ⇧⌘G, blur the clip, ⌘G — and it is what `Frame`'s doc in `nest.rs`
    /// records as a limit of the flattening rather than of this op.
    ///
    /// `Err` for an unknown clip, for a nest, for a source with no pixel
    /// size — a text clip, an audio-only one, or a degenerate shape, which
    /// have nothing to scale to the canvas — and for a clip carrying no
    /// video properties at all. `Err` too when
    /// the extra track or clip would break a reader cap, which
    /// [`Project::finish`] reports through `validate`. Never an identity: a copy
    /// on a new empty track can neither be an identity nor break the overlap
    /// rule, so there is nothing here to refuse quietly.
    pub fn add_blurred_background(&self, clip: u32) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let (mut next, track) = self.with_back_track();
        let id = next.allocate_id();
        let copy = self.blurred_copy(&target, id, track)?;
        next.clips.push(copy);
        self.finish(next)
    }

    /// The blurred copy of `target` with id `id` on track `track`: what
    /// [`Project::add_blurred_background`] places, and what `reframe_clip`'s
    /// backdrop places (spec §11 VR-25). `Err` for a nest, a source with no
    /// pixel size and a clip with no video properties, in that order — the
    /// op's own sentences.
    pub(crate) fn blurred_copy(&self, target: &Clip, id: u32, track: u32) -> Result<Clip, String> {
        let clip = target.id;
        if matches!(target.source, Source::Nest { .. }) {
            return Err(format!(
                "clip {clip} shows a nest, whose own filters the flattening drops, \
                 so a blurred copy of it would come out sharp"
            ));
        }
        let Some((source_width, source_height)) = self.source_size(target) else {
            return Err(format!(
                "clip {clip}'s source has no pixel size, so nothing can be scaled to fill the canvas"
            ));
        };
        let Some(video) = target.video.clone() else {
            return Err(format!("clip {clip} has no video properties"));
        };

        let mut copy = target.clone();
        copy.id = id;
        copy.track = track;
        // The pair `detach_audio` sets, read the other way: this half of the
        // clip is the picture, and the sound stays with the original.
        copy.enabled = Enabled {
            video: true,
            audio: false,
        };
        // The one field of the audio group that is not about this clip's own
        // sound. `duckers` gathers a duck from the flattened timeline with no
        // test of `enabled.audio`, a mute or a solo, so a copy that kept one
        // would duck the whole mix — the clip it was copied from included,
        // since the copy is a voice on no track and the `others` filter has
        // nothing to exclude it by. A picture command may not change the
        // sound, and no rendered frame could catch it if it did.
        copy.audio = copy.audio.map(|audio| AudioProps {
            duck: None,
            ..audio
        });
        copy.transition_in = None;
        copy.actions = Vec::new();
        copy.name = Some(BLURRED_BACKGROUND_NAME.to_string());
        copy.label = None;
        copy.video = Some(VideoProps {
            scale: self.fill_scale(source_width, source_height),
            x: 0.0,
            y: 0.0,
            crop: Crop::default(),
            filters: vec![Filter {
                kind: FilterKind::Blur,
                amount: 1.0,
            }],
            // A plate composites with the CANVAS, never with a mode chosen
            // for the picture in front of it — over the default black that
            // mode is either destructive or inert. The module doc argues it.
            blend: BlendMode::Normal,
            // And it does not MOVE (format version 8). A backdrop that slid
            // in, spun or pulsed behind the clip it was copied from would
            // be two pictures of one recording disagreeing about where they
            // are, which is the visible half of the same mistake as keeping
            // the audio switch — and a slide would leave the canvas showing
            // down one side, which is the one thing a background exists to
            // prevent.
            motion: None,
            // A backdrop cut down to the person is no backdrop (CO-20).
            cutout: None,
            // Nor is one cut by the person in front of it (CO-52).
            behind_subject: false,
            // Drawn behind and sharp, so it drops the blur (CU-113).
            motion_blur: 0.0,
            ..video
        });
        Ok(copy)
    }
}

1	//! What the mattes do at one instant (spec §11 MT-2, MT-5; §7.3): each
2	//! recipe layer's `matte` — the group it is drawn INTO, if its track is a
3	//! matte, and the groups that CUT it — and the recipe's `mattes` list, the
4	//! groups the compositor draws before the destination pass (MT-6).
5	//!
6	//! A matte is read per instant and per pair of tracks: no clip names
7	//! another, so nothing here is stored and no edit can break a link. The
8	//! walk is over the [`Instance`]s the recipe already covers at `t` — the
9	//! drawing ones, so a hidden matte track or a clip with its video off has no
10	//! instance, draws into nothing, and leaves the track behind uncut (MT-2).
11	//!
12	//! ### Levels
13	//!
14	//! A layer inside `n` nest clips has `n + 1` LEVELS: its own track in the
15	//! innermost container, then each enclosing nest clip's track in ITS
16	//! container, outward to the timeline. Walking them inner to outer, the
17	//! first level whose track is a matte track makes the layer a matte source
18	//! (`into`), and no level outside it applies; every level before it whose
19	//! track is a matte's target cuts the layer (MT-5). A group is one
20	//! [`MatteKey`]: the matte track's id and the nest clips enclosing its
21	//! container, so two clips showing one nest at one instant each have their
22	//! own matte.
23	//!
24	//! ### The contract the compositor relies on
25	//!
26	//! Ids are dense from 0 in first-seen order, walking layers back to front,
27	//! a layer's `into` before its cuts. Every layer whose first matte level is
28	//! a matte track names its group in `into`, listed or not — that is how the
29	//! compositor knows not to draw it on the canvas. A group is LISTED when at
30	//! least one layer is drawn into it and at least one is cut by it; `cut`
31	//! names only listed groups, ascending; `mattes` runs deepest container
32	//! first (the longest path), then by id.
33	
34	use serde_json::{Map, Value};
35	
36	use crate::evaluate::json;
37	use crate::model::{Project, Track, TrackMatte};
38	use crate::nest::Instance;
39	
40	/// The track a matte track cuts (MT-2): the track directly behind it in its
41	/// own container, when that track is not itself a matte track. `None` for an
42	/// ordinary track, a back-most matte track, a matte in front of a matte and
43	/// an id the container does not hold.
44	pub(crate) fn matte_target(tracks: &[Track], track: u32) -> Option<u32> {
45	    let index = tracks.iter().position(|t| t.id == track)?;
46	    let matte = tracks.get(index)?;
47	    if matte.matte.is_none() {
48	        return None;
49	    }
50	    let behind = tracks.get(index.checked_sub(1)?)?;
51	    behind.matte.is_none().then_some(behind.id)
52	}
53	
54	/// The matte track whose target is `track`, if any: the track directly in
55	/// front of it, when [`matte_target`] answers `track` for it.
56	fn cutting_matte(tracks: &[Track], track: u32) -> Option<&Track> {
57	    let index = tracks.iter().position(|t| t.id == track)?;
58	    let front = tracks.get(index.checked_add(1)?)?;
59	    (matte_target(tracks, front.id) == Some(track)).then_some(front)
60	}
61	
62	/// One matte at one instant (MT-5): the ids of the nest clips enclosing its
63	/// track's container, outermost first — an instance path's prefix — and the
64	/// matte track's id.
65	#[derive(Debug, Clone, PartialEq, Eq)]
66	pub(crate) struct MatteKey {
67	    pub path: Vec<u32>,
68	    pub track: u32,
69	}
70	
71	/// What [`Project::frame_mattes`] answers: per instance, in the order given,
72	/// the layer's `matte` value and whether it is drawn into a matte (and so
73	/// never onto the canvas); and the recipe's `mattes` list.
74	pub(crate) struct FrameMattes {
75	    pub layer: Vec<Value>,
76	    pub drawn_into: Vec<bool>,
77	    pub listed: Value,
78	}
79	
80	/// One layer's roles before ids are given: the matte it is drawn into, and
81	/// every matte whose target it sits on, innermost first.
82	struct Roles {
83	    into: Option<(MatteKey, TrackMatte)>,
84	    cuts: Vec<(MatteKey, TrackMatte)>,
85	}
86	
87	impl Project {
88	    /// The mattes at the instant `instances` cover (spec §7.3): one entry
89	    /// per instance, in their order, and the listed groups. See the module
90	    /// doc for the contract.
91	    pub(crate) fn frame_mattes(&self, instances: &[Instance<'_>]) -> FrameMattes {
92	        let roles: Vec<Roles> = instances.iter().map(|i| self.matte_roles(i)).collect();
93	
94	        // A group is listed when something is drawn into it AND something
95	        // is cut by it: a matte with nothing to cut, or a target with no
96	        // matte clip showing, costs the compositor nothing.
97	        let listed = |key: &MatteKey| {
98	            roles
99	                .iter()
100	                .any(|r| r.into.as_ref().is_some_and(|(k, _)| k == key))
101	                && roles.iter().any(|r| r.cuts.iter().any(|(k, _)| k == key))
102	        };
103	
104	        let mut groups: Vec<(MatteKey, TrackMatte)> = Vec::new();
105	        let mut id_of = |key: &MatteKey, mode: TrackMatte| -> usize {
106	            match groups.iter().position(|(k, _)| k == key) {
107	                Some(found) => found,
108	                None => {
109	                    groups.push((key.clone(), mode));
110	                    groups.len() - 1
111	                }
112	            }
113	        };
114	
115	        let mut layer = Vec::with_capacity(roles.len());
116	        let mut drawn_into = Vec::with_capacity(roles.len());
117	        for role in &roles {
118	            let into = role.into.as_ref().map(|(k, mode)| id_of(k, *mode));
119	            let mut cut: Vec<usize> = role
120	                .cuts
121	                .iter()
122	                .filter(|(k, _)| listed(k))
123	                .map(|(k, mode)| id_of(k, *mode))
124	                .collect();
125	            cut.sort_unstable();
126	            drawn_into.push(into.is_some());
127	            layer.push(if into.is_none() && cut.is_empty() {
128	                Value::Null
129	            } else {
130	                let mut entry = Map::new();
131	                entry.insert("into".to_string(), into.map_or(Value::Null, Value::from));
132	                entry.insert(
133	                    "cut".to_string(),
134	                    Value::Array(cut.into_iter().map(Value::from).collect()),
135	                );
136	                Value::Object(entry)
137	            });
138	        }
139	
140	        // Deepest container first, so a matte drawn inside a nest is ready
141	        // before a matte that nest's composite belongs to; then by id.
142	        let mut order: Vec<usize> = (0..groups.len())
143	            .filter(|i| groups.get(*i).is_some_and(|(k, _)| listed(k)))
144	            .collect();
145	        order.sort_by_key(|i| {
146	            let depth = groups.get(*i).map_or(0, |(k, _)| k.path.len());
147	            (std::cmp::Reverse(depth), *i)
148	        });
149	        let mattes = order
150	            .into_iter()
151	            .filter_map(|i| groups.get(i).map(|(_, mode)| (i, *mode)))
152	            .map(|(id, mode)| {
153	                let mut entry = Map::new();
154	                entry.insert("group".to_string(), Value::from(id));
155	                entry.insert("mode".to_string(), json(&mode));
156	                Value::Object(entry)
157	            })
158	            .collect();
159	
160	        FrameMattes {
161	            layer,
162	            drawn_into,
163	            listed: Value::Array(mattes),
164	        }
165	    }
166	
167	    /// One layer's levels walked inner to outer (MT-5): the first matte
168	    /// track met is the layer's `into` and ends the walk; each level up to
169	    /// it whose track a matte targets adds that matte to the cuts.
170	    fn matte_roles(&self, instance: &Instance<'_>) -> Roles {
171	        let depth = instance.inside.len();
172	        let mut cuts = Vec::new();
173	        for level in (0..=depth).rev() {
174	            let track = if level == depth {
175	                instance.track
176	            } else {
177	                match instance.inside.get(level) {
178	                    Some(enclosing) => enclosing.track,
179	                    None => break,
180	                }
181	            };
182	            let tracks: &[Track] = match level.checked_sub(1) {
183	                Some(up) => match instance.inside.get(up) {
184	                    Some(enclosing) => &enclosing.nest.tracks,
185	                    None => break,
186	                },
187	                None => &self.tracks,
188	            };
189	            let path: Vec<u32> = instance
190	                .inside
191	                .iter()
192	                .take(level)
193	                .map(|e| e.clip.id)
194	                .collect();
195	            // Asked before the matte test, so that `matte_target` alone
196	            // says a matte track is nobody's target (MT-2): a matte in front
197	            // of a matte cuts nothing because of that rule, not because of
198	            // the order of these two tests.
199	            if let Some(front) = cutting_matte(tracks, track.id) {
200	                let key = MatteKey {
201	                    path: path.clone(),
202	                    track: front.id,
203	                };
204	                cuts.push((key, front.matte));
205	            }
206	            if !track.matte.is_none() {
207	                let key = MatteKey {
208	                    path,
209	                    track: track.id,
210	                };
211	                return Roles {
212	                    into: Some((key, track.matte)),
213	                    cuts,
214	                };
215	            }
216	        }
217	        Roles { into: None, cuts }
218	    }
219	}
220	//! The matte vocabulary (format version 14, spec §11 MT-1): [`TrackMatte`],
221	//! what a track's clips do to the track directly behind it.
222	//!
223	//! A matte is a TRACK relation, not a clip property: a clip is a matte only
224	//! by the track it sits on, so moving it off makes it ordinary and no clip
225	//! ever names another (MT-2). The field holding it is `Track.matte` in
226	//! `model.rs`; what a matte cuts at an instant is `recipe_matte.rs`'s.
227	//!
228	//! Re-exported whole by `model_props.rs`, which `model.rs` re-exports whole
229	//! in turn, so `crate::model::TrackMatte` resolves like every other
230	//! property type.
231	//!
232	//! **The declaration ORDER is a shader discriminant** (MT-3): `none` is 0
233	//! and `luma_inverted` 4, `TrackMatte.shaderCode` on the Swift side is the
234	//! case index and `Compositor.metal`'s `kMatte*` constants compare against
235	//! the same integers — so a mode is appended, never inserted, like
236	//! [`crate::model::BlendMode`]'s and [`crate::model::ObscureKind`]'s. The
237	//! JSON spelling of each variant is persisted, so a rename needs a migration
238	//! step. Closed: a misspelt mode is refused at the serde boundary naming the
239	//! five, because there is no neutral matte to fall back to.
