267	/// A track's matte (format version 14, spec §11 MT-1), mirroring
268	/// `core/src/model_matte.rs`'s `TrackMatte`: what the track's clips do to
269	/// the track directly behind it — nothing (`none`, an ordinary track), or
270	/// cut it by their alpha, inverted alpha, Rec. 709 luma or inverted luma.
271	///
272	/// **The case ORDER is a shader discriminant** (MT-3): `shaderCode` is the
273	/// case index, `Compositor.metal`'s `kMatteNone`…`kMatteLumaInverted`
274	/// compare against the same integers, and the core declares the variants in
275	/// the same order. Append, never reorder — `BlendMode`'s rule.
276	enum TrackMatte: String, Codable, CaseIterable {
277	    case none
278	    case alpha
279	    case alphaInverted = "alpha_inverted"
280	    case luma
281	    case lumaInverted = "luma_inverted"
282	
283	    /// The word a person reads for the mode: the menu row (MT-7) and the
284	    /// header's tag.
285	    var displayName: String {
286	        switch self {
287	        case .none: return "Off"
288	        case .alpha: return "Alpha"
289	        case .alphaInverted: return "Inverted Alpha"
290	        case .luma: return "Luma"
291	        case .lumaInverted: return "Inverted Luma"
292	        }
293	    }
294	
295	    /// The code the matte resolve pass's uniform carries: the case index,
296	    /// `none` 0 to `lumaInverted` 4.
297	    var shaderCode: Float { Float(TrackMatte.allCases.firstIndex(of: self) ?? 0) }
298	
299	    /// The track `track` cuts (MT-2), the core's `matte_target` for the
300	    /// CHROME only — the header's tag, the lane's bracket and the Clip tab's
301	    /// note; what is drawn is the recipe's. The track directly behind it in
302	    /// `tracks` (one container, back first), when that track is not itself a
303	    /// matte track; nil for an ordinary track, a back-most matte track, a
304	    /// matte in front of a matte and an id `tracks` does not hold.
305	    static func target(of track: UInt32, in tracks: [TrackSnapshot]) -> UInt32? {
306	        guard let index = tracks.firstIndex(where: { $0.id == track }),
307	              tracks[index].matte != .none, index > 0
308	        else { return nil }
309	        let behind = tracks[index - 1]
310	        return behind.matte == .none ? behind.id : nil
311	    }
312	}
