243	/// How a matte track's picture cuts the track directly behind it (MT-3):
244	/// by its alpha, its inverted alpha, its Rec. 709 luma or its inverted
245	/// luma. `None` — the default — is an ordinary track.
246	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
247	#[serde(rename_all = "snake_case")]
248	pub enum TrackMatte {
249	    #[default]
250	    None,
251	    Alpha,
252	    AlphaInverted,
253	    Luma,
254	    LumaInverted,
255	}
