295	    /// The code the matte resolve pass's uniform carries: the case index,
296	    /// `none` 0 to `lumaInverted` 4.
297	    var shaderCode: Float { Float(TrackMatte.allCases.firstIndex(of: self) ?? 0) }
298	
299	    /// The track `track` cuts (MT-2), the core's `matte_target` for the
300	    /// CHROME only — the header's tag, the lane's bracket and the Clip tab's
301	    /// note; what is drawn is the recipe's. The track directly behind it in
302	    /// `tracks` (one container, back first), when that track is not itself a
303	    /// matte track; nil for an ordinary track, a back-most matte track, a
304	    /// matte in front of a matte and an id `tracks` does not hold.
305	    static func target(of track: UInt32, in tracks: [TrackSnapshot]) -> UInt32? {
306	        guard let index = tracks.firstIndex(where: { $0.id == track }),
307	              tracks[index].matte != .none, index > 0
308	        else { return nil }
309	        let behind = tracks[index - 1]
310	        return behind.matte == .none ? behind.id : nil
311	    }
312	}
