392	/// edits: the mode is set by Track ▸ Matte (`EditorViewController+Matte.swift`)
393	/// and the context menu's Matte submenu (`TimelineView+TrackMenu.swift`).
394	enum TimelineMatteTag {
395	    /// The tag's words, and whether it is dimmed: nil for an ordinary track,
396	    /// "Matte · <mode>" for a matte track with a target, and a dimmed
397	    /// "Matte · nothing behind" for one with none — a back-most matte track,
398	    /// or one in front of another matte track (MT-2).
399	    static func text(
400	        for track: TrackSnapshot, in tracks: [TrackSnapshot]
401	    ) -> (text: String, dimmed: Bool)? {
402	        guard track.matte != .none else { return nil }
403	        guard TrackMatte.target(of: track.id, in: tracks) != nil else {
404	            return ("Matte · nothing behind", true)
405	        }
406	        return ("Matte · \(track.matte.displayName)", false)
