409	    static let font = DS.sans(9, weight: .semibold)
410	    /// The tag's box: its text plus `padding` a side, `height` tall.
411	    static let padding: CGFloat = 3
412	    static let height: CGFloat = 11
413	    /// The name label's box ends 15 pt down the row (`TimelineHeaderView.draw`:
414	    /// y + 2, 13 tall); the tag's own line starts there.
415	    static let ownLineTop: CGFloat = 15
416	    /// The room between the tag on the name's line and the name it clips.
417	    static let gap: CGFloat = 4
418	    /// A matte lane's clips (MT-7): half opacity, the whole body passes as
419	    /// one transparency layer so overlapping strokes do not double up.
420	    static let laneOpacity: CGFloat = 0.5
421	
422	    static func width(of text: String) -> CGFloat {
423	        ceil(text.size(withAttributes: [.font: font]).width) + 2 * padding
424	    }
425	
426	    /// The least the name keeps beside a tag on its line (MT-7).
427	    static let minimumNameWidth: CGFloat = 40
428	    /// The tag's words on the name's line of a row `rowWidth` wide: "Matte"
429	    /// alone when the full words would leave the name less than
430	    /// `minimumNameWidth` (MT-7).
431	    static func fitted(_ text: String, rowWidth: CGFloat) -> String {
432	        rowWidth - 14 - width(of: text) - gap < minimumNameWidth ? "Matte" : text
433	    }
434	
435	    /// The tag's text colour: the primary label colour, or for a dimmed tag
436	    /// the muted one — never the accent, so its legibility does not depend
437	    /// on the accent the owner picked (MT-7).
438	    static func textColor(dimmed: Bool) -> NSColor { dimmed ? DS.textMuted : DS.textStrong }
