503	    /// when the track in front of it is a matte that cuts it, so a redraw of
504	    /// either lane alone repaints the bracket where it crosses that lane.
505	    func drawMatteLane(
506	        track: TrackSnapshot, rects: [CGRect], lane: CGRect, owner: TimelineView,
507	        body: () -> Void
508	    ) {
509	        let tracks = owner.snapshot.tracks
510	        guard track.matte != .none, let context = NSGraphicsContext.current?.cgContext else {
511	            body()
512	            if let index = tracks.firstIndex(where: { $0.id == track.id }),
513	               tracks.indices.contains(index + 1),
514	               TrackMatte.target(of: tracks[index + 1].id, in: tracks) == track.id {
515	                drawMatteBracket(from: tracks[index + 1].id, to: track.id, owner: owner)
516	            }
517	            return
518	        }
