520	        context.setAlpha(TimelineMatteTag.laneOpacity)
521	        // The layer spans the lane alone: every pass draws inside it.
522	        context.beginTransparencyLayer(in: lane, auxiliaryInfo: nil)
523	        body()
524	        context.endTransparencyLayer()
